#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_length_returns_correct_length_for_nonempty_string(void) {
    // Setup: create a buffer with a known string
    const char *test_str = "hello world";
    buffer_t *buf = buffer_new_with_copy(test_str);
    TEST_ASSERT_NOT_NULL(buf);

    // Test: call buffer_length
    size_t len = buffer_length(buf);

    // Assert: length matches strlen(test_str)
    TEST_ASSERT_EQUAL(strlen(test_str), len);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_length_returns_correct_length_for_nonempty_string);
    return UNITY_END();
}

